add(B/'scene-data.mjs','author-b/scene-data.mjs',[("export function buildScene(edit='baseline') {\n  if(!Object.hasOwn(EDITS,edit)) throw new Error(`Unknown edit: ${edit}`);\n  const p={...BASELINE,...EDITS[edit]}, meshes=[], matrix=assemblyMatrix(p);","import { parametersFor } from '../contract.mjs';\nexport function buildScene(edit='baseline') {\n  const p=parametersFor(edit), meshes=[], matrix=assemblyMatrix(p);")])
add(A/'scene-system.mjs','author-a/scene-system.mjs',[("import { STATES, parametersFor }", "import { STATES, parametersFor, INITIAL_EDIT }"),("this.scene = constructScene('baseline');","this.scene = constructScene(INITIAL_EDIT);")])
add(A/'main.mjs','author-a/main.mjs',[("import { CONFIG, CAMERAS, PALETTE }", "import { STATES } from '/harness/contract.mjs';\nimport { CONFIG, CAMERAS, PALETTE }"),("phase: 'complete', states:29","phase: 'complete', states:STATES.length"),("nativeSubmission: receipt.details,","nativeSubmission: receipt.details, transport: nativeRenderer.getDiagnostics({detail:'full'}).transport,")])
for name in ['worker.mjs','gpu-observer.mjs','native-evidence.mjs','frame-proof.mjs']: add(A/name,'author-a/'+name)
add(A/'index.html','author-a/index.html',[("Crane courtyard · Aperture independent author A","Crane combined edits · post-author Aperture regression")])
add(B/'scene.mjs','author-b/scene.mjs',[("}, 60000)", "}, 180000)")])
for name in ['worker.mjs','checks.mjs','native-meshes.mjs','gpu-evidence.mjs','lighting.mjs']: add(B/name,'author-b/'+name)
add(B/'index.html','author-b/index.html',[("Crane courtyard — three.js native WebGPU","Crane combined edits · post-author three.js regression")])
add(H/'client.mjs','harness/client.mjs',[("validateEvidence, verifyNativeProof", "validateEvidence, verifyNativeProof, validateTransition"),("  let baseline = null;","  let baseline = null;\n  let previousEvidence = null;"),("      validateEvidence(evidence, state, receipt);","      validateEvidence(evidence, state, receipt);\n      validateTransition(evidence, state, previousEvidence, adapter.engine);\n      previousEvidence = evidence;")])
add(H/'checks.mjs','harness/base-checks.mjs',[("export function validateStateRecord(record, expectedIndex) {\n  const state = STATES[expectedIndex];","export function validateStateRecord(record, expectedIndex, selectedStates = STATES) {\n  const state = selectedStates[expectedIndex];")])
add(H/'recorder.mjs','harness/recorder.mjs',[("validateStateRecord, verifyNativeProof", "validateStateRecord, verifyNativeProof, validateTransition"),("{ engine }) {","{ engine, states = STATES }) {"),("const state = stateMatch ? STATES.find", "const state = stateMatch ? states.find"),("STATES[state.index - 1]", "states[state.index - 1]"),("validateStateRecord(record, state.index);","validateStateRecord(record, state.index, states);\n          validateTransition(record.evidence, state, records.at(-1)?.evidence ?? null, engine);"),("value.states === STATES.length && records.length === STATES.length", "value.states === states.length && records.length === states.length"),("value.artifacts.length === STATES.length * 2", "value.artifacts.length === states.length * 2"),("const expected = STATES.flatMap", "const expected = states.flatMap"),("      if (channels === 4 && row[x + 3] === 0) continue;", "      requireValue(channels !== 4 || row[x + 3] === 255, 'Canvas PNG must be fully opaque');"),("export function inspectCanvasPng(bytes) {", "export function inspectCanvasPng(bytes, { includePixels = false } = {}) {"),("  let previous = Buffer.alloc(stride), first = null, nonuniformPixels = 0, visiblePixels = 0;", "  const rgb = includePixels ? Buffer.alloc(width * height * 3) : null;\n  let previous = Buffer.alloc(stride), first = null, nonuniformPixels = 0, visiblePixels = 0;"),("      visiblePixels++;", "      if (rgb) for (let c = 0; c < 3; c++) rgb[(y * width + x / channels) * 3 + c] = row[x + c];\n      visiblePixels++;"),("blankCheck: 'passed' };", "blankCheck: 'passed', ...(rgb ? { rgb } : {}) };")])
def derived(src,replacements):
    original=src.read_text(); result=original
    for old,new in replacements:
        if result.count(old)!=1: raise RuntimeError(f'Expected exactly one seam in {src}: {old!r}')
        result=result.replace(old,new)
    return original,result
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');p.add_argument('--refresh',action='store_true');args=p.parse_args()
    if args.refresh and (ROOT/'source-pins.json').exists():raise RuntimeError('Frozen fixture cannot be refreshed')
    entries=[];patch=[]
    for src,dest,replacements in SPECS:
        original,result=derived(src,replacements);target=ROOT/dest
        if args.check:
            if target.read_text()!=result: raise RuntimeError(f'Derived bytes differ: {target}')
        else:
            with target.open('w' if args.refresh else 'x') as f:f.write(result)
        entries.append({'source':str(src.relative_to(REPO)),'destination':str(target.relative_to(REPO)),'sourceSha256':hashlib.sha256(original.encode()).hexdigest(),'derivedSha256':hashlib.sha256(result.encode()).hexdigest(),'replacements':[{'old':a,'new':b} for a,b in replacements]})
        patch.extend(difflib.unified_diff(original.splitlines(True),result.splitlines(True),fromfile=str(src.relative_to(REPO)),tofile=str(target.relative_to(REPO))))
    result=json.dumps({'scope':'post-author adapter-only derivation','files':entries},indent=2)+'\n'
    if args.check:
        if (ROOT/'derivation.json').read_text()!=result or (ROOT/'derivation.diff').read_text()!=''.join(patch):raise RuntimeError('Derivation manifest/diff differs')
    else:
        (ROOT/'derivation.json').write_text(result);(ROOT/'derivation.diff').write_text(''.join(patch))
    print(json.dumps({'ok':True,'files':len(entries),'exactMechanicalDerivation':True,'mode':'check' if args.check else 'prepare'}))
